code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    holes = []
    for r in range(h):
        for c in range(1, w - 1):
            color = out[r][c - 1]
            if out[r][c] == 0 and color != 0 and out[r][c + 1] == color:
                holes.append((r, c, color))
                out[r][c] = color
    for r, c, color in holes:
        for rr in range(r - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    for c in range(w):
        if out[h - 1][c] == 0:
            continue
        color = out[h - 1][c]
        top = h - 1
        while top > 0 and out[top - 1][c] == color:
            top -= 1
        for rr in range(top - 1, -1, -1):
            if out[rr][c] != 0:
                break
            out[rr][c] = color
    return out
'''
